def fit(cols):
    A=np.column_stack(cols+[np.ones_like(t)])
    c,res,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    r=dv_dt-A@c
    return c, np.mean(r**2)/np.var(dv_dt)
